// Тикет #b398d352 (b398d35241bbead5460a9f7f) — заголовок молитвы по центру, עבר QA 13.10.2026 (iPhone, TestFlight 1.0.0 (19)), проведён пользователем.
// Факт 13.10 (скрин b398d352-ios-b19-prayer-title-centered.png): «התחל תפילה» на главной (активна только в окне молитвы, напр. מנחה с 12:55) →
// экран молитвы; заголовок «מנחה (אשכנזי) ⌄» = элемент label «בחירת נוסח. הנוסח המוצג: אשכנזי», рамка x=117, w=168 → центр 201 при ширине 402.
// Критерий: |центр рамки − ширина экрана / 2| ≤ 4 pt. В тикете также «ערבית …» — проверка та же для любой текущей молитвы (ערבית 13.10 не проверялась).
// Вне окна молитвы «התחל תפילה» неактивна → skip с причиной. Экран «תפילות» не используется (падает в сборке 19, баг #70e8283a).
import { driver, expect } from '@wdio/globals';
import { byLabel, byLabelStartsWith } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { skipWith } from '../_lib/app-0710.ts';
import { rectOf } from '../_lib/app-1310.ts';

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-09 Заголовок молитвы «<תפילה> (<נוסח>) ⌄» по центру экрана (±4 pt) #b398d352 @prod-safe', async function () {
    const start = await byLabel('התחל תפילה');
    await start.waitForDisplayed({ timeout: 20000 });
    if (!(await start.isEnabled())) skipWith(this, '«התחל תפילה» неактивна — вне окна молитвы; повторить в окне שחרית/מנחה/ערבית');
    await start.click();

    const title = await byLabelStartsWith('בחירת נוסח');
    await title.waitForDisplayed({ timeout: 20000 });
    const r = await rectOf(title);
    const { width } = await driver.getWindowSize();
    const center = r.x + r.width / 2;
    console.log(`[GP-09] «${await title.getAttribute(driver.isAndroid ? 'content-desc' : 'label')}»: x=${r.x} w=${r.width} центр=${center}, экран/2=${width / 2}`);
    expect(Math.abs(center - width / 2)).toBeLessThanOrEqual(driver.isAndroid ? 4 * 3 : 4);   // Android — пиксели (~3 px на pt)
  });
});
